$ErrorActionPreference="Stop";$base="http://localhost:3000/api";function Assert($c,$m){if(-not $c){throw $m}}
Write-Host "[1/4] Health/readiness" -ForegroundColor Cyan;$h=Invoke-RestMethod "$base/health";$rdy=Invoke-RestMethod "$base/health/ready";Assert ($h.status-eq"ok") "Health falhou";Assert ($rdy.status-eq"ready") "Readiness falhou"
Write-Host "[2/4] Request ID" -ForegroundColor Cyan;$r=Invoke-WebRequest -UseBasicParsing "$base/health" -Headers @{"x-request-id"="wise-regression-v1"};Assert ($r.Headers["x-request-id"]-eq"wise-regression-v1") "Request ID falhou"
Write-Host "[3/4] Regressao dos lotes" -ForegroundColor Cyan;$scripts=@("smoke-sales-finance.ps1","smoke-operations-v2.ps1","smoke-commercial-fiscal.ps1","smoke-treasury-finance-v2.ps1","smoke-procurement-commercial-v2.ps1","smoke-logistics-commercial-v3.ps1","smoke-production-pcp-v1.ps1","smoke-crm-services-v1.ps1");foreach($s in $scripts){$p=Join-Path $PSScriptRoot $s;if(Test-Path $p){Write-Host " -> $s";& powershell -ExecutionPolicy Bypass -File $p;if($LASTEXITCODE-ne 0){throw "Falha em $s"}}}
Write-Host "[4/4] Done" -ForegroundColor Cyan;Write-Host "REGRESSION PLATFORM HARDENING V1 CONCLUIDA COM SUCESSO." -ForegroundColor Green
